let vmin, vmax;
let gl, glsl;
let mx, my, me = 0.015;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1771364/files/shader.vert', 'shader.frag');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  smooth();
  noStroke();
  gl = drawingContext;
  vmin = max(width, height);
  vmax = max(width, height);
  mx = width / 2;
  my = height / 2;
}

function spherical(radius, theta, phi, thetaOffset, phiOffset, detailX, detailY) {
  let gId = `spherical|${theta}|${phi}|${thetaOffset}|${phiOffset}|${detailX}|${detailY}`;
  if (!this._renderer.geometryInHash(gId)) {
    let cb = function(detailX, detailY) {
      let u, v, p;
      for (let i = 0; i <= this.detailY; i++) {
        v = i / this.detailY;
        for (let j = 0; j <= this.detailX; j++) {
          u = j / this.detailX;
          p = new p5.Vector(u - 0.5, v - 0.5, 0);
          let t = u * theta + thetaOffset;
          let f = v * phi + phiOffset;
          let r = 1 + (1 - v) * 0.6;
          p.x = sin(t) * cos(f) * r;
          p.y = sin(f) * r;
          p.z = cos(t) * cos(f) * r; 
          this.vertices.push(p);
          this.vertexNormals.push(p);
          this.uvs.push(u, v);
        }
      }
    };
    let geom = new p5.Geometry(detailX, detailY, cb);
    geom.computeFaces().computeNormals();
    this._renderer.createBuffers(gId, geom);
  }
  this._renderer.drawBuffersScaled(gId, radius, radius, radius);
}

function draw() {
  let sec = millis() / 1000;
  let NUM = 8;
  let radius = vmin / 4;
  let theta = PI * 2;
  let phi = PI * 0.18;
  let thetaOffset = 0;
  let phiOffset = -phi;
  let detailX = 128;
  let detailY = 32;
  mx += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mx) * me;
  my += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - my) * me;
  let rx = PI * map(my, 0, height, -0.25, 0);
  let ry = PI * map(mx, 0, width, 0.5, -0.5);

  background(20);

  rotateX(rx);
  rotateY(ry);

  gl.enable(gl.DEPTH_TEST);
  gl.depthFunc(gl.ALWAYS);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE);

  fill(255);
  push();
  {
    shader(glsl);

    glsl.setUniform('uTime', sec);
    spherical(radius*1.2, theta, phi, thetaOffset, phiOffset, detailX, detailY);

    glsl.setUniform('uTime', -sec * 2);
    spherical(radius, theta, phi * 0.8, thetaOffset, phiOffset * 0.8, detailX, detailY);
  }
  pop();
}

